CARDIO.register({"item":"p211","meta":{"num":"p211","label":"211","spe":"pneumo","short":"Sarcoïdose","title":"Sarcoïdose","section":"P","chapter":15,"pages":"231-245","sdd":[]},"objectives":[{"id":"p211-obj-01","rank":"A","rubric":"Contenu multimédia","title":"Photographie d'un exemple typique d'érythème noueux","desc":""},{"id":"p211-obj-02","rank":"A","rubric":"Définition","title":"Connaître la définition de la sarcoïdose","desc":""},{"id":"p211-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Connaître les critères du diagnostic d'une sarcoïdose","desc":""},{"id":"p211-obj-04","rank":"A","rubric":"Diagnostic positif","title":"Connaître les formes fréquentes de la sarcoïdose : atteintes respiratoires, le syndrome de Löfgren et l'érythème noueux","desc":""},{"id":"p211-obj-05","rank":"B","rubric":"Diagnostic positif","title":"Connaître les principales manifestations extra-respiratoires","desc":""},{"id":"p211-obj-06","rank":"B","rubric":"Diagnostic positif","title":"Connaître les éléments cliniques nécessitant de chercher des diagnostics différentiels","desc":""},{"id":"p211-obj-07","rank":"B","rubric":"Physiopathologie","title":"Connaître les mécanismes de la réaction inflammatoire conduisant au granulome","desc":""},{"id":"p211-obj-08","rank":"B","rubric":"Étiologies","title":"Connaître les principales causes de granulomatoses secondaires","desc":""},{"id":"p211-obj-09","rank":"B","rubric":"Ex. complémentaires","title":"Connaître l'intérêt et les limites des principaux tests biologiques","desc":""},{"id":"p211-obj-10","rank":"B","rubric":"Ex. complémentaires","title":"Connaître les indications des examens d'imagerie devant une sarcoïdose","desc":""},{"id":"p211-obj-11","rank":"B","rubric":"Ex. complémentaires","title":"Connaître la place de l'anatomie pathologique pour le diagnostic et la stratégie des prélèvements","desc":""},{"id":"p211-obj-12","rank":"B","rubric":"Ex. complémentaires","title":"Connaître les anomalies des explorations fonctionnelles respiratoires typiques","desc":""},{"id":"p211-obj-13","rank":"B","rubric":"Épidémiologie","title":"Connaître l'épidémiologie de la sarcoïdose (âge, sexe de survenue, et prévalence variable selon les ethnies)","desc":""},{"id":"p211-obj-14","rank":"B","rubric":"Suivi et/ou pronostic","title":"Connaître l'évolution souvent bénigne de la sarcoïdose, et la rémission dans 90% des cas de syndrome de Löfgren","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p211-qroc-001","type":"QROC","rank":"A","objective":"p211-obj-02","tags":["définition"],"difficulty":1,"question":"Comment qualifie-t-on la sarcoïdose quant à son étendue et à sa cause ?","answer":"Maladie systémique, de cause inconnue","accept":["systemique de cause inconnue","maladie systemique de cause inconnue","systemique et de cause inconnue","systemique cause inconnue"],"keywords":["systemique","inconnue"],"explanation":"La sarcoïdose est une maladie systémique de cause inconnue ; le diagnostic suppose d'avoir éliminé les causes connues de granulomes.","src":"p. 231-232"},{"id":"p211-qroc-002","type":"QROC","rank":"A","objective":"p211-obj-02","tags":["définition","diagnostic"],"difficulty":1,"question":"Quelle lésion histologique caractérise la sarcoïdose dans les organes atteints ?","answer":"Un granulome épithélioïde et giganto-cellulaire sans nécrose caséeuse","accept":["granulome sans necrose caseeuse","granulomes sans necrose caseeuse","granulome epithelioide et giganto cellulaire","granulome tuberculoide sans necrose caseeuse","granulomes epithelioides et giganto cellulaires sans necrose caseeuse"],"keywords":["granulom","necrose"],"explanation":"Les organes atteints sont infiltrés par des granulomes immuns épithélioïdes et giganto-cellulaires (dits aussi tuberculoïdes), sans nécrose caséeuse.","src":"p. 232"},{"id":"p211-qroc-003","type":"QROC","rank":"A","objective":"p211-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Sur quels trois éléments repose le diagnostic de sarcoïdose ?","answer":"Tableau compatible, granulomes typiques, autres granulomatoses éliminées","accept":["tableau clinique compatible granulomes typiques elimination des autres granulomatoses","clinique compatible granulomes elimination des autres granulomatoses","clinique granulomes exclusion des autres granulomatoses"],"keywords":["granulome","granulomatose"],"explanation":"Il faut un tableau clinico-radiographique évocateur ou au moins compatible, la mise en évidence de granulomes typiques sans nécrose caséeuse, et l'élimination des autres granulomatoses.","src":"p. 242"},{"id":"p211-qroc-004","type":"QROC","rank":"A","objective":"p211-obj-03","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quels tableaux cliniques, associés à des adénopathies médiastino-hilaires bilatérales, dispensent de biopsie car ils sont quasi pathognomoniques ?","answer":"Syndrome de Löfgren, syndrome de Heerfordt, lupus pernio","accept":["lofgren heerfordt lupus pernio","lofgren heerfordt pernio","syndrome de lofgren syndrome de heerfordt lupus pernio"],"keywords":["lofgren","heerfordt","pernio"],"explanation":"Le syndrome de Löfgren, le syndrome d'Heerfordt et le lupus pernio, associés à des adénopathies médiastino-hilaires bilatérales, ne nécessitent pas de biopsie. Sinon, la mise en évidence de granulomes reste le plus souvent nécessaire.","src":"p. 242"},{"id":"p211-qroc-005","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["définition","clinique"],"difficulty":1,"question":"Quelle association définit le syndrome de Löfgren ?","answer":"Érythème noueux + adénopathies hilaires et médiastinales bilatérales","accept":["erytheme noueux et adenopathies hilaires bilaterales","erytheme noueux adenopathies hilaires et mediastinales","erytheme noueux et adenopathies hilaires et mediastinales bilaterales","erytheme noueux adenopathies hilaires bilaterales"],"keywords":["noueux","hilaire"],"explanation":"Le syndrome de Löfgren, forme aiguë de sarcoïdose souvent fébrile, associe un érythème noueux et des adénopathies hilaires et médiastinales bilatérales ; des arthralgies ou arthrites des chevilles peuvent remplacer l'érythème noueux.","src":"p. 231, 239-240"},{"id":"p211-qroc-006","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["clinique","pièges"],"difficulty":2,"question":"Pourquoi la biopsie d'un érythème noueux de sarcoïdose est-elle inutile ?","answer":"Lésion aspécifique : pas de granulome","accept":["lesion aspecifique","aspecifique","pas de granulome","sans granulome","ne montre pas de granulome"],"keywords":["granulome"],"explanation":"L'érythème noueux est une dermo-hypodermite inflammatoire aiguë aspécifique : la biopsie ne montre pas de granulome et n'apporte rien au diagnostic.","src":"p. 239"},{"id":"p211-qroc-007","type":"QROC","rank":"A","objective":"p211-obj-01","tags":["clinique"],"difficulty":1,"question":"Sur quelles faces des membres l'érythème noueux prédomine-t-il ?","answer":"Les faces d'extension, notamment les jambes","accept":["faces d extension","face d extension","faces d extension des membres","face d extension des jambes"],"keywords":["extension"],"explanation":"L'érythème noueux est une dermo-hypodermite inflammatoire aiguë qui prédomine sur les faces d'extension des membres, notamment les jambes. La sarcoïdose en est la cause la plus fréquente en France.","src":"p. 239"},{"id":"p211-qroc-008","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["épidémiologie","clinique"],"difficulty":1,"question":"Quelle proportion de patients atteints de sarcoïdose a une atteinte médiastino-pulmonaire ?","answer":"Environ 90 %","accept":["90","90 %","environ 90 %","90 pour cent"],"keywords":["90"],"explanation":"L'atteinte médiastino-pulmonaire est présente chez environ 90 % des patients et isolée dans la moitié des cas ; elle est très utile au diagnostic.","src":"p. 231-232"},{"id":"p211-qroc-009","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["clinique"],"difficulty":1,"question":"Que retrouve habituellement l'auscultation pulmonaire dans la sarcoïdose ?","answer":"Elle est généralement normale","accept":["auscultation normale","generalement normale","elle est normale","auscultation generalement normale"],"keywords":["normal"],"explanation":"L'auscultation est généralement normale, avec une toux le plus souvent non productive et une dyspnée rare au début. Des râles crépitants sont atypiques et doivent faire rechercher un diagnostic différentiel.","src":"p. 233, 244"},{"id":"p211-qroc-010","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["clinique","imagerie"],"difficulty":2,"question":"Quel contraste clinico-radiologique habituel est un élément en faveur du diagnostic de sarcoïdose ?","answer":"Radiographie très atteinte, symptômes discrets, auscultation normale","accept":["atteinte radiographique importante et symptomatologie discrete","radiographie tres atteinte symptomes discrets","atteinte radiographique importante symptomes discrets auscultation normale"],"keywords":["radiograph","discret"],"explanation":"L'importance de l'atteinte radiographique pulmonaire contraste avec la discrétion des symptômes respiratoires et la normalité de l'auscultation : c'est habituel et en faveur de la sarcoïdose.","src":"p. 234"},{"id":"p211-qroc-011","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["imagerie"],"difficulty":2,"question":"Quel est l'aspect typique des adénopathies hilaires de la sarcoïdose à la radiographie ?","answer":"Bilatérales, symétriques, homogènes, non compressives","accept":["bilaterales symetriques homogenes non compressives","bilaterales symetriques et non compressives","bilaterales et symetriques"],"keywords":["bilat","symetr"],"explanation":"Les adénopathies hilaires sont bilatérales, symétriques, homogènes et non compressives dans 95 % des cas. Des adénopathies asymétriques ou compressives doivent faire éliminer formellement un diagnostic alternatif.","src":"p. 234"},{"id":"p211-qroc-012","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["imagerie"],"difficulty":1,"question":"Que montre la radiographie de thorax au stade I de la sarcoïdose ?","answer":"Des adénopathies hilaires bilatérales, sans atteinte parenchymateuse","accept":["adenopathies hilaires bilaterales sans atteinte parenchymateuse","adenopathies sans atteinte parenchymateuse","adenopathies hilaires et mediastinales sans atteinte parenchymateuse","adenopathies sans atteinte pulmonaire"],"keywords":["adenopathie","parenchym"],"explanation":"Stade I : adénopathies hilaires bilatérales et médiastinales sans atteinte parenchymateuse. Le stade II y associe une atteinte parenchymateuse, le stade III est une atteinte parenchymateuse isolée, le stade IV est une fibrose.","src":"p. 233"},{"id":"p211-qroc-013","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["imagerie"],"difficulty":2,"question":"Quelle atteinte caractérise le stade III radiographique de la sarcoïdose, par rapport au stade II ?","answer":"Une atteinte parenchymateuse pulmonaire isolée","accept":["atteinte parenchymateuse isolee","atteinte parenchymateuse pulmonaire isolee","atteinte parenchymateuse seule","parenchyme sans adenopathie"],"keywords":["parenchym","isolee"],"explanation":"Stade III : atteinte parenchymateuse pulmonaire isolée, sans les adénopathies du stade I. Cette atteinte réalise un aspect micronodulaire diffus prédominant dans les parties moyennes et supérieures des champs pulmonaires.","src":"p. 233-234"},{"id":"p211-qroc-014","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["imagerie","complications"],"difficulty":1,"question":"Quelle lésion définit le stade IV radiographique de la sarcoïdose ?","answer":"La fibrose pulmonaire (souvent apicale)","accept":["fibrose pulmonaire","fibrose","fibrose apicale"],"keywords":["fibrose"],"explanation":"Le stade IV correspond à la fibrose pulmonaire, souvent à prédominance apicale (opacités rétractiles avec ascension des hiles). Les stades III et IV font partie des critères pronostiques défavorables.","src":"p. 233-234, 245"},{"id":"p211-qroc-015","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["clinique"],"difficulty":2,"question":"Quel terrain est préférentiellement touché par le syndrome de Löfgren ?","answer":"La femme originaire d'Europe du Nord","accept":["femme d europe du nord","femme originaire d europe du nord","femme nordique","femme europe du nord"],"keywords":["femme","nord"],"explanation":"Le syndrome de Löfgren, forme aiguë de sarcoïdose souvent fébrile, touche préférentiellement la femme originaire d'Europe du Nord.","src":"p. 239"},{"id":"p211-qroc-016","type":"QROC","rank":"A","objective":"p211-obj-04","tags":["clinique"],"difficulty":2,"question":"Qu'est-ce qui peut remplacer l'érythème noueux dans le syndrome de Löfgren, notamment chez l'homme ?","answer":"Des arthralgies ou arthrites des chevilles","accept":["arthrites des chevilles","arthralgies des chevilles","arthrite des chevilles","arthralgies ou arthrites des chevilles"],"keywords":["cheville"],"explanation":"Des arthralgies ou arthrites des chevilles sont souvent associées à l'érythème noueux et peuvent le remplacer, notamment chez l'homme.","src":"p. 239-240"},{"id":"p211-qroc-017","type":"QROC","rank":"B","objective":"p211-obj-14","tags":["suivi","complications"],"difficulty":2,"question":"Dans quelle proportion de cas le syndrome de Löfgren guérit-il spontanément, en 12 à 24 mois ?","answer":"Plus de 90 %","accept":["plus de 90 %","plus de 90","superieur a 90 %","plus de 90 pour cent"],"keywords":["plus","90"],"explanation":"Le syndrome de Löfgren est spontanément résolutif dans plus de 90 % des cas, en 12 à 24 mois ; c'est une forme aiguë de sarcoïdose.","src":"p. 231, 240, 244"},{"id":"p211-qroc-018","type":"QROC","rank":"B","objective":"p211-obj-14","tags":["suivi"],"difficulty":2,"question":"Quelle durée d'évolution définit une sarcoïdose aiguë, par opposition à la forme chronique ?","answer":"Moins de 2 ans","accept":["moins de 2 ans","moins de deux ans","inferieure a 2 ans"],"keywords":["moins","2"],"explanation":"La sarcoïdose est dite aiguë si elle évolue depuis moins de 2 ans, chronique à partir de 3 à 5 ans. Près de la moitié des patients ont une résolution spontanée dans les 2 ans ; après 5 ans, une rémission est très peu probable.","src":"p. 244"},{"id":"p211-qroc-019","type":"QROC","rank":"B","objective":"p211-obj-14","tags":["complications","suivi"],"difficulty":1,"question":"Quel est le principal risque évolutif de la sarcoïdose pulmonaire ?","answer":"L'évolution vers la fibrose pulmonaire","accept":["fibrose pulmonaire","fibrose","evolution vers la fibrose"],"keywords":["fibrose"],"explanation":"La fibrose pulmonaire peut entraîner une insuffisance respiratoire chronique, une hypertension pulmonaire et une infection aspergillaire chronique ; c'est la principale cause de mortalité par sarcoïdose en Occident.","src":"p. 231, 245"},{"id":"p211-qroc-020","type":"QROC","rank":"B","objective":"p211-obj-14","tags":["complications"],"difficulty":2,"question":"Quelle infection chronique, source d'hémoptysies, menace les cavités de la fibrose sarcoïdienne ?","answer":"L'infection aspergillaire chronique (aspergillome)","accept":["aspergillome","aspergillose","aspergillose pulmonaire chronique","infection aspergillaire"],"keywords":["aspergill"],"explanation":"Les lésions cavitaires de la fibrose exposent à la greffe aspergillaire (aspergillome, aspergillose pulmonaire chronique) avec risque d'hémoptysies. Au scanner, l'aspergillome apparaît comme une image en grelot déclive.","src":"p. 234, 236, 245"},{"id":"p211-qroc-021","type":"QROC","rank":"B","objective":"p211-obj-14","tags":["suivi"],"difficulty":2,"question":"À quel rythme revoit-on les patients atteints de sarcoïdose jusqu'à ce que la guérison soit assurée ?","answer":"Tous les 3 à 6 mois","accept":["3 a 6 mois","tous les 3 a 6 mois","3 6 mois","trimestriel ou semestriel"],"keywords":["3","6"],"explanation":"Les patients sont revus tous les 3 à 6 mois avec radiographie de thorax et EFR, ECA et biologie sanguine, ECG ; le but est de détecter précocement les localisations menaçant le pronostic vital ou fonctionnel.","src":"p. 244"},{"id":"p211-qroc-022","type":"QROC","rank":"B","objective":"p211-obj-05","tags":["clinique","ECG"],"difficulty":1,"question":"Quel examen est indispensable au diagnostic de n'importe quelle forme de sarcoïdose et à renouveler périodiquement ?","answer":"L'électrocardiogramme (ECG)","accept":["ecg","electrocardiogramme","l electrocardiogramme"],"keywords":["ecg"],"explanation":"La sarcoïdose cardiaque est la deuxième cause de mortalité de la maladie (insuffisance cardiaque, mort subite par trouble de conduction de haut grade ou du rythme ventriculaire) : l'ECG est indispensable et doit être renouvelé.","src":"p. 240, 242"},{"id":"p211-qroc-023","type":"QROC","rank":"B","objective":"p211-obj-05","tags":["urgence","clinique"],"difficulty":2,"question":"Quelles sont les deux situations d'urgence de la sarcoïdose ?","answer":"Hypercalcémie et trouble de conduction cardiaque","accept":["hypercalcemie et trouble de conduction","hypercalcemie et troubles de la conduction","hypercalcemie et bav","hypercalcemie troubles conduction"],"keywords":["hypercalc","conduction"],"explanation":"Sont à identifier en urgence l'hypercalcémie (5 à 10 % des cas, favorisée par le soleil, les apports calciques et la vitamine D) et les troubles de conduction cardiaque (BAV, bloc de branche), qui peuvent causer une mort subite.","src":"p. 231, 240-241"},{"id":"p211-qroc-024","type":"QROC","rank":"B","objective":"p211-obj-05","tags":["clinique"],"difficulty":2,"question":"Quelle atteinte faut-il rechercher devant un lupus pernio ?","answer":"Une atteinte ORL","accept":["orl","atteinte orl","une atteinte orl"],"keywords":["orl"],"explanation":"Le lupus pernio est une plaque violacée infiltrée du nez et des joues (aspect en aile de papillon), observée surtout dans les formes chroniques ; il doit faire rechercher une atteinte ORL.","src":"p. 239"},{"id":"p211-qroc-025","type":"QROC","rank":"B","objective":"p211-obj-05","tags":["clinique"],"difficulty":2,"question":"Quel syndrome associe uvéo-parotidite bilatérale fébrile, paralysie faciale (ou autre nerf crânien) et méningite lymphocytaire aseptique ?","answer":"Le syndrome de Heerfordt","accept":["heerfordt","syndrome de heerfordt","syndrome d heerfordt"],"keywords":["heerfordt"],"explanation":"Le syndrome de Heerfordt fait partie, avec le syndrome de Löfgren et le lupus pernio, des tableaux quasi pathognomoniques qui dispensent de biopsie lorsqu'ils s'associent à des adénopathies médiastino-hilaires bilatérales.","src":"p. 240, 242"},{"id":"p211-qroc-026","type":"QROC","rank":"B","objective":"p211-obj-05","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quel examen ophtalmologique confirme une uvéite antérieure aiguë (œil rouge, baisse d'acuité visuelle) ?","answer":"L'examen à la lampe à fente","accept":["lampe a fente","examen a la lampe a fente","examen a la lampe fente"],"keywords":["fente"],"explanation":"Le diagnostic d'uvéite antérieure repose sur l'examen à la lampe à fente. Une uvéite postérieure, parfois latente, impose une consultation ophtalmologique systématique car elle menace le pronostic visuel.","src":"p. 238"},{"id":"p211-qroc-027","type":"QROC","rank":"B","objective":"p211-obj-06","tags":["clinique","pièges"],"difficulty":2,"question":"Quel signe des doigts, exceptionnel dans la sarcoïdose, doit faire rechercher un diagnostic alternatif ?","answer":"L'hippocratisme digital","accept":["hippocratisme digital","hippocratisme","doigts hippocratiques"],"keywords":["hippocrat"],"explanation":"L'hippocratisme digital est exceptionnel dans la sarcoïdose. Comme les râles crépitants, la fièvre hors syndrome de Löfgren ou l'hypogammaglobulinémie, il est atypique et impose de chercher un diagnostic différentiel.","src":"p. 233, 244"},{"id":"p211-qroc-028","type":"QROC","rank":"B","objective":"p211-obj-06","tags":["clinique","pièges"],"difficulty":2,"question":"Devant une fièvre inexpliquée (hors syndrome de Löfgren) au cours d'une sarcoïdose, quels diagnostics faut-il éliminer ?","answer":"Une infection, notamment tuberculeuse, ou un lymphome","accept":["infection et lymphome","tuberculose et lymphome","infection tuberculose lymphome","infection ou lymphome","tuberculose ou lymphome"],"keywords":["lymphome"],"explanation":"La fièvre est rare dans la sarcoïdose en dehors du syndrome de Löfgren, d'une uvéo-parotidite fébrile et d'une atteinte hépatique ou rénale ; sinon elle doit faire éliminer une infection (notamment une tuberculose) ou un lymphome.","src":"p. 241"},{"id":"p211-qroc-029","type":"QROC","rank":"B","objective":"p211-obj-09","tags":["biologie","pièges"],"difficulty":2,"question":"Dans quelle situation le dosage de l'ECA sérique est-il ininterprétable ?","answer":"Chez les patients traités par IEC","accept":["iec","inhibiteurs de l enzyme de conversion","traitement par iec","sous iec"],"keywords":["conversion"],"explanation":"L'ECA, produite par les macrophages activés des granulomes, n'est élevée que dans environ 60 % des cas et n'est pas spécifique ; elle est ininterprétable chez les patients qui prennent un inhibiteur de l'enzyme de conversion.","src":"p. 241"},{"id":"p211-qroc-030","type":"QROC","rank":"B","objective":"p211-obj-09","tags":["biologie"],"difficulty":2,"question":"Quel résultat du test tuberculinique est habituel (environ 80 % des cas) dans la sarcoïdose ?","answer":"Négatif (anergie tuberculinique)","accept":["negatif","negative","anergie","anergie tuberculinique","negativation"],"keywords":["negati"],"explanation":"Le test tuberculinique est négatif dans environ 80 % des cas (anergie) et c'est surtout sa négativation qui oriente ; la sarcoïdose ne s'accompagne pas d'un déficit immunitaire. Une intradermo-réaction positive est atypique.","src":"p. 241, 244"},{"id":"p211-qroc-031","type":"QROC","rank":"B","objective":"p211-obj-10","tags":["imagerie"],"difficulty":2,"question":"Pour quelle présentation radiographique typique le scanner thoracique n'est-il pas indispensable ?","answer":"Adénopathies sans atteinte pulmonaire (stade I typique)","accept":["adenopathies sans atteinte pulmonaire","adenopathies sans atteinte parenchymateuse","adenopathies hilaires bilaterales seules"],"keywords":["adenopathie"],"explanation":"Le scanner n'est pas indispensable en cas de stade I typique ; il est généralement utile dans les autres cas, et indispensable si la présentation est non typique ou si l'on suspecte une complication (fibrose, hypertension pulmonaire, aspergillome, néoplasie).","src":"p. 235"},{"id":"p211-qroc-032","type":"QROC","rank":"B","objective":"p211-obj-10","tags":["imagerie"],"difficulty":2,"question":"Quelle distribution caractérise les micronodules de la sarcoïdose au scanner thoracique ?","answer":"Lymphatique (périlymphatique)","accept":["lymphatique","perilymphatique","peri lymphatique","distribution lymphatique"],"keywords":["lymphatique"],"explanation":"Les micronodules, confluents et bilatéraux, prédominent dans la moitié supérieure des poumons le long des axes péribroncho-vasculaires, des zones sous-pleurales et des scissures (aspect « perlé »). Une distribution non lymphatique est atypique.","src":"p. 235, 244"},{"id":"p211-qroc-033","type":"QROC","rank":"B","objective":"p211-obj-11","tags":["diagnostic"],"difficulty":2,"question":"Quels sites de prélèvement privilégie-t-on en premier pour obtenir la preuve histologique d'une sarcoïdose ?","answer":"Les sites d'accès aisé (peau, ganglion périphérique…)","accept":["sites d acces aise","site d acces aise","acces aise","lesion cutanee","adenopathie peripherique","glandes salivaires accessoires"],"keywords":["acces"],"explanation":"Les sites de prélèvement sont hiérarchisés selon leur caractère invasif, leur rentabilité et les organes atteints : on privilégie d'abord les sites d'accès aisé (lésion cutanée, adénopathie périphérique, glandes salivaires accessoires, nodule conjonctival).","src":"p. 243"},{"id":"p211-qroc-034","type":"QROC","rank":"B","objective":"p211-obj-11","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Quel prélèvement endoscopique est proposé en première intention en l'absence de lésion superficielle accessible ?","answer":"Des biopsies bronchiques étagées d'éperons proximaux","accept":["biopsies bronchiques","biopsies d eperons bronchiques","biopsies etagees d eperons","biopsies bronchiques etagees","biopsies d eperons"],"keywords":["biopsie","bronchi"],"explanation":"Les biopsies bronchiques étagées proximales ont un bon rendement (sensibilité de 50 à 60 % pour les granulomes, plus élevée si la muqueuse est anormale). Si elles sont négatives, on discute biopsies transbronchiques, ponction ganglionnaire écho-guidée, etc.","src":"p. 237, 243"},{"id":"p211-qroc-035","type":"QROC","rank":"B","objective":"p211-obj-11","tags":["biologie","diagnostic"],"difficulty":2,"question":"Quel rapport lymphocytaire du LBA, s'il est augmenté (notamment > 3,5), évoque la sarcoïdose sans suffire à l'affirmer ?","answer":"Le rapport CD4/CD8","accept":["cd4 cd8","rapport cd4 cd8","le rapport cd4 cd8"],"keywords":["cd4"],"explanation":"Le LBA révèle une alvéolite lymphocytaire modérée (20 à 50 %) à lymphocytes T CD4+ ; un rapport CD4/CD8 élevé est un argument en faveur de la sarcoïdose, mais il est inconstant et insuffisant pour conclure.","src":"p. 237"},{"id":"p211-qroc-036","type":"QROC","rank":"B","objective":"p211-obj-12","tags":["paraclinique"],"difficulty":2,"question":"Quelle anomalie de la fonction d'échange du poumon est précoce au cours de la sarcoïdose ?","answer":"Une diminution de la DLCO","accept":["baisse de la dlco","diminution de la dlco","dlco abaissee","dlco diminuee","diminution de la diffusion alveolo capillaire"],"keywords":["dlco"],"explanation":"La DLCO, qui reflète la diffusion alvéolo-capillaire, diminue précocement ; la spirométrie est normale ou peu altérée au stade I et les gaz du sang restent longtemps normaux au repos.","src":"p. 236"},{"id":"p211-qroc-037","type":"QROC","rank":"B","objective":"p211-obj-13","tags":["épidémiologie"],"difficulty":2,"question":"Quelle population a une sarcoïdose trois fois plus fréquente et plus sévère ?","answer":"Les Afro-Américains et Caribéens","accept":["afro americains","afro caribeens","afro americains caribeens","afro americains et caribeens","origine afro caribeenne"],"keywords":["afro"],"explanation":"La sarcoïdose est trois fois plus fréquente et plus sévère chez les Afro-Américains et Caribéens ; elle est aussi fréquente dans les pays nordiques d'Europe et rare en Asie de l'Est. En France, la prévalence est de 30 pour 100 000.","src":"p. 232"},{"id":"p211-qroc-038","type":"QROC","rank":"B","objective":"p211-obj-07","tags":["physiopathologie"],"difficulty":2,"question":"Quels lymphocytes prédominent dans l'infiltrat lymphocytaire du granulome sarcoïdien ?","answer":"Les lymphocytes T CD4+","accept":["lymphocytes t cd4","lt cd4","t cd4","cd4"],"keywords":["cd4"],"explanation":"Le granulome associe cellules épithélioïdes et géantes issues de la lignée monocyto-macrophagique et infiltrat lymphocytaire T à prédominance CD4+, avec une fibrose inconstante. Sa formation suit probablement une stimulation par des antigènes de l'environnement sur un terrain génétique prédisposé.","src":"p. 232"},{"id":"p211-qroc-039","type":"QROC","rank":"B","objective":"p211-obj-08","tags":["étiologie"],"difficulty":3,"question":"Quels médicaments ciblant PD-1 ou PD-L1 peuvent induire une granulomatose sarcoid-like ?","answer":"Les inhibiteurs de check point immunitaire","accept":["inhibiteurs de check point","inhibiteurs du check point immunitaire","check point","checkpoint","inhibiteurs de checkpoint"],"keywords":["check"],"explanation":"Certains médicaments (inhibiteurs de check-point immunitaire, interféron, anti-TNF, BCG intra-vésical) ou la reconstitution immunitaire d'un patient infecté par le VIH peuvent induire une granulomatose sarcoid-like, qui fait partie des diagnostics différentiels.","src":"p. 243"},{"id":"p211-qroc-040","type":"QROC","rank":"B","objective":"p211-obj-14","tags":["suivi"],"difficulty":2,"question":"Comment définit-on la guérison de la sarcoïdose ?","answer":"Rémission stable hors traitement pendant 3 ans","accept":["remission stable hors traitement pendant 3 ans","remission stable pendant 3 ans","3 ans de remission hors traitement","remission de 3 ans sans traitement"],"keywords":["remission","3"],"explanation":"On parle de guérison après 3 ans de rémission stable sans aucun traitement ; les rechutes surviennent le plus souvent 2 à 6 mois après l'arrêt du traitement et deviennent exceptionnelles passé 3 ans sans traitement.","src":"p. 244"},{"id":"p211-qcm-101","type":"QRM","rank":"A","objective":"p211-obj-02","tags":["définition","diagnostic"],"difficulty":1,"stem":"À propos de la définition de la sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"C'est une maladie systémique.","ok":true,"why":"Les manifestations extra-thoraciques sont polymorphes et, associées à l'atteinte médiastino-pulmonaire, affirment le caractère systémique."},{"t":"Sa cause est inconnue.","ok":true,"why":"L'étiologie reste inconnue ; on suspecte une stimulation par des antigènes de l'environnement sur un terrain génétique prédisposé."},{"t":"Elle se caractérise par des granulomes épithélioïdes et giganto-cellulaires.","ok":true,"why":"Ce sont les granulomes dits tuberculoïdes, sans nécrose caséeuse."},{"t":"Les granulomes comportent typiquement une nécrose caséeuse.","ok":false,"why":"Les granulomes de la sarcoïdose sont dépourvus de nécrose caséeuse."},{"t":"Elle est toujours limitée au poumon et aux ganglions médiastinaux, sans localisation extra-thoracique.","ok":false,"why":"L'atteinte médiastino-pulmonaire est très fréquente (environ 90 %), mais les localisations extra-thoraciques sont polymorphes."}],"explanation":"La sarcoïdose est une maladie systémique de cause inconnue, caractérisée par des granulomes épithélioïdes et giganto-cellulaires sans nécrose caséeuse ; le diagnostic suppose d'avoir éliminé les causes connues de granulomes.","src":"p. 231-232"},{"id":"p211-qcm-102","type":"QRM","rank":"A","objective":"p211-obj-03","tags":["diagnostic","pièges"],"difficulty":2,"stem":"À propos du diagnostic de sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"Il associe tableau compatible, granulomes typiques et exclusion des autres granulomatoses.","ok":true,"why":"Ce sont les trois éléments du diagnostic."},{"t":"Un syndrome de Löfgren avec adénopathies médiastino-hilaires bilatérales dispense de biopsie.","ok":true,"why":"Ce tableau, comme le syndrome d'Heerfordt ou le lupus pernio, est quasi pathognomonique."},{"t":"Un test tuberculinique positif est un argument en faveur de la sarcoïdose.","ok":false,"why":"Le test est négatif dans environ 80 % des cas (anergie) ; une intradermo-réaction positive est atypique."},{"t":"Une ECA sérique élevée suffit à affirmer le diagnostic, sans preuve histologique.","ok":false,"why":"L'ECA est peu sensible (environ 60 %) et non spécifique ; aucun examen biologique n'est spécifique de la sarcoïdose."},{"t":"Un stade I asymptomatique impose obligatoirement une biopsie, même sous surveillance spécialisée.","ok":false,"why":"Un stade I asymptomatique sous surveillance spécialisée n'implique pas obligatoirement de biopsie."}],"explanation":"Le diagnostic repose sur un tableau clinico-radiographique compatible, des granulomes typiques sans nécrose caséeuse et l'élimination des autres granulomatoses ; certains tableaux quasi pathognomoniques dispensent de biopsie.","src":"p. 241-242"},{"id":"p211-qcm-103","type":"QRM","rank":"A","objective":"p211-obj-04","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Une femme de 28 ans, originaire d'Europe du Nord, consulte pour une fièvre et des nodules rouges douloureux des jambes, avec des arthralgies des chevilles. La radiographie de thorax montre des adénopathies hilaires bilatérales sans atteinte parenchymateuse. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'un syndrome de Löfgren.","ok":true,"why":"Érythème noueux et adénopathies hilaires et médiastinales bilatérales : forme aiguë de sarcoïdose, souvent fébrile, préférentiellement chez la femme originaire d'Europe du Nord."},{"t":"L'évolution est spontanément résolutive dans plus de 90 % des cas en 12 à 24 mois.","ok":true,"why":"Le syndrome de Löfgren est une forme aiguë qui évolue favorablement sans traitement."},{"t":"La biopsie cutanée d'un nodule d'érythème noueux n'est pas utile.","ok":true,"why":"L'érythème noueux est une lésion aspécifique : la biopsie ne montre pas de granulome."},{"t":"Une biopsie pulmonaire est indispensable pour affirmer le diagnostic.","ok":false,"why":"Ce tableau, quasi pathognomonique associé aux adénopathies bilatérales, ne nécessite pas de biopsie."},{"t":"La biopsie de l'érythème noueux montrerait des granulomes épithélioïdes sans nécrose caséeuse.","ok":false,"why":"L'érythème noueux est une lésion aspécifique, sans granulome."}],"explanation":"Érythème noueux (ou arthrites des chevilles) plus adénopathies hilaires et médiastinales bilatérales définissent le syndrome de Löfgren, d'évolution spontanément résolutive dans plus de 90 % des cas.","trap":"Ne pas biopsier un érythème noueux : la lésion est aspécifique.","src":"p. 239-240, 242"},{"id":"p211-qcm-104","type":"QRM","rank":"A","objective":"p211-obj-04","tags":["imagerie"],"difficulty":2,"stem":"À propos des stades radiographiques de la sarcoïdose médiastino-pulmonaire, quelles associations « stade – aspect » sont exactes ?","options":[{"t":"Stade I : adénopathies hilaires bilatérales sans atteinte parenchymateuse","ok":true,"why":"C'est la définition du stade I (adénopathies hilaires bilatérales et médiastinales)."},{"t":"Stade II : adénopathies et atteinte parenchymateuse","ok":true,"why":"Le stade II associe adénopathies et atteinte parenchymateuse pulmonaire."},{"t":"Stade III : atteinte parenchymateuse isolée","ok":true,"why":"Le stade III est une atteinte parenchymateuse sans adénopathies associées."},{"t":"Stade IV : radiographie de thorax normale, sans adénopathie ni atteinte parenchymateuse","ok":false,"why":"Le stade IV correspond à la fibrose pulmonaire, souvent à prédominance apicale ; la radiographie normale est le stade 0."},{"t":"Stade 0 : fibrose pulmonaire apicale avec ascension des hiles","ok":false,"why":"Le stade 0 est une radiographie normale (formes extra-thoraciques) ; la fibrose est le stade IV."}],"explanation":"Cinq stades radiographiques sont individualisés (0 à IV) et corrélés à la probabilité de guérison spontanée ; ils reposent sur la radiographie standard, et non sur le scanner.","src":"p. 233, 235"},{"id":"p211-qcm-105","type":"QRM","rank":"A","objective":"p211-obj-04","tags":["clinique","imagerie"],"difficulty":2,"stem":"À propos de l'atteinte médiastino-pulmonaire de la sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"Elle est présente chez environ 90 % des patients et isolée dans la moitié des cas.","ok":true,"why":"Elle est très fréquente et très utile au diagnostic."},{"t":"La toux est fréquente, le plus souvent non productive, et la dyspnée est rare au début.","ok":true,"why":"La dyspnée se rencontre surtout dans les formes avancées."},{"t":"L'auscultation pulmonaire est généralement normale.","ok":true,"why":"Des râles crépitants sont atypiques et doivent faire rechercher un autre diagnostic."},{"t":"Une radiographie très atteinte avec peu de symptômes est en faveur du diagnostic.","ok":true,"why":"Ce contraste entre radiographie et clinique est habituel dans la sarcoïdose."},{"t":"L'hippocratisme digital est un signe fréquent, qui oriente vers une forme avancée de la maladie.","ok":false,"why":"Il est exceptionnel et doit faire éliminer un diagnostic alternatif."}],"explanation":"La sarcoïdose médiastino-pulmonaire est typiquement pauci-symptomatique et son auscultation normale malgré l'importance des anomalies radiographiques.","src":"p. 231-234, 244"},{"id":"p211-qcm-106","type":"QRM","rank":"B","objective":"p211-obj-06","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Quels éléments sont atypiques dans le cadre d'une sarcoïdose et doivent faire rechercher un diagnostic différentiel ?","options":[{"t":"Des râles crépitants à l'auscultation.","ok":true,"why":"L'auscultation est généralement normale : des râles crépitants sont atypiques."},{"t":"Un hippocratisme digital.","ok":true,"why":"Il est exceptionnel dans la sarcoïdose."},{"t":"Une intradermo-réaction à la tuberculine positive.","ok":true,"why":"Le test tuberculinique est négatif dans environ 80 % des cas ; sa positivité est atypique."},{"t":"Des adénopathies médiastinales unilatérales ou compressives.","ok":true,"why":"Les adénopathies typiques sont hilaires, bilatérales, symétriques et non compressives."},{"t":"Des micronodules de distribution lymphatique au scanner thoracique.","ok":false,"why":"C'est la distribution caractéristique de la sarcoïdose ; c'est la distribution non lymphatique qui est atypique."}],"explanation":"Sont atypiques et imposent un diagnostic différentiel : début à un âge atypique, fièvre ou signes généraux hors Löfgren, râles crépitants, hippocratisme digital, micronodules non lymphatiques, adénopathies compressives ou unilatérales, IDR positive, hypogammaglobulinémie, sérologie VIH positive.","src":"p. 233-234, 244"},{"id":"p211-qcm-107","type":"QRM","rank":"B","objective":"p211-obj-08","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"À propos des autres causes de granulomes épithélioïdes et giganto-cellulaires à éliminer avant de conclure à une sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"Des infections, dont la tuberculose, doivent être éliminées.","ok":true,"why":"Les infections (tuberculose, mycobactéries non tuberculeuses, brucellose, mycoses…) figurent en tête des causes à exclure."},{"t":"Certains médicaments (anti-TNF, interféron, check-point) peuvent induire des granulomes.","ok":true,"why":"Granulomatose sarcoid-like, qui peut aussi être induite par le BCG intra-vésical."},{"t":"Une sérologie VIH positive est un argument en faveur de la sarcoïdose.","ok":false,"why":"Elle est atypique et impose de chercher un diagnostic différentiel (granulomatose lors de la reconstitution immunitaire du patient infecté par le VIH)."},{"t":"Les lymphomes ne s'accompagnent jamais de réaction granulomateuse.","ok":false,"why":"Les réactions granulomateuses péri-tumorales (lymphomes, chorion de certains carcinomes) font partie des diagnostics différentiels."},{"t":"La sarcoïdose s'accompagne d'un déficit immunitaire qui explique la formation des granulomes.","ok":false,"why":"La sarcoïdose ne s'accompagne pas d'un déficit immunitaire ; le déficit immunitaire commun variable est, lui, un diagnostic différentiel."}],"explanation":"Le tableau des autres causes de granulomes comprend les infections, certains médicaments, les réactions péri-tumorales, les expositions particulaires (bérylliose, talcose, silicose), le déficit immunitaire commun variable, certaines maladies inflammatoires et auto-immunes, et les pneumopathies d'hypersensibilité.","src":"p. 241, 243"},{"id":"p211-qcm-108","type":"QRM","rank":"B","objective":"p211-obj-09","tags":["biologie"],"difficulty":2,"stem":"Quelles anomalies biologiques peuvent s'observer au cours de la sarcoïdose ?","options":[{"t":"Une hypercalciurie, fréquente.","ok":true,"why":"Elle résulte d'une élévation du calcitriol, liée à la sécrétion de 1α-hydroxylase par les macrophages sarcoïdiens."},{"t":"Une lymphopénie prédominant sur les lymphocytes T CD4+.","ok":true,"why":"C'est une anomalie biologique classique de la maladie."},{"t":"Une hypergammaglobulinémie polyclonale.","ok":true,"why":"Elle témoigne de l'activation des lymphocytes B."},{"t":"Un test tuberculinique négatif dans 80 % des cas.","ok":true,"why":"C'est l'anergie tuberculinique ; c'est surtout sa négativation qui a une valeur d'orientation."},{"t":"Une hypogammaglobulinémie, signe habituel de la maladie.","ok":false,"why":"Elle est atypique et doit faire rechercher un diagnostic différentiel (déficit immunitaire commun variable)."}],"explanation":"La sarcoïdose s'accompagne volontiers d'hypercalciurie, de lymphopénie CD4+, d'hypergammaglobulinémie polyclonale et d'un test tuberculinique négatif ; aucun examen biologique n'est spécifique.","src":"p. 241-242, 244"},{"id":"p211-qcm-109","type":"QRM","rank":"B","objective":"p211-obj-09","tags":["biologie","urgence"],"difficulty":2,"stem":"À propos de l'hypercalcémie de la sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"Une exposition solaire peut la favoriser, surtout l'été.","ok":true,"why":"L'exposition solaire est à déconseiller en cas de troubles du métabolisme calcique."},{"t":"Une prise de vitamine D ou des apports calciques majorés peuvent la favoriser.","ok":true,"why":"Ces apports augmentent l'absorption intestinale du calcium déjà majorée par le calcitriol."},{"t":"Elle est due à une baisse du calcitriol circulant, par déficit de 1α-hydroxylase.","ok":false,"why":"Le calcitriol est élevé : les macrophages sarcoïdiens sécrètent de la 1α-hydroxylase."},{"t":"Elle touche plus de la moitié des patients.","ok":false,"why":"Elle survient dans 5 à 10 % des cas ; c'est l'hypercalciurie qui est fréquente."},{"t":"L'exposition solaire est recommandée en cas de troubles du métabolisme calcique.","ok":false,"why":"Elle est à déconseiller."}],"explanation":"L'hypercalcémie, observée dans 5 à 10 % des cas, est l'une des deux urgences de la sarcoïdose ; elle est favorisée par le soleil, les apports calciques et la vitamine D.","src":"p. 231, 241"},{"id":"p211-qcm-110","type":"QRM","rank":"B","objective":"p211-obj-05","tags":["clinique","urgence","ECG"],"difficulty":2,"stem":"À propos de la sarcoïdose cardiaque, quelles propositions sont exactes ?","options":[{"t":"Elle représente la deuxième cause de mortalité de la sarcoïdose.","ok":true,"why":"Par insuffisance cardiaque ou mort subite liée à un trouble de conduction de haut grade ou à un trouble du rythme ventriculaire."},{"t":"L'ECG est indispensable dans toute forme de sarcoïdose et à renouveler.","ok":true,"why":"Même sans symptôme cardiaque : il est indispensable au diagnostic de n'importe quelle forme et à répéter périodiquement."},{"t":"Elle peut se révéler par un BAV ou un bloc de branche, surtout droit.","ok":true,"why":"Les troubles de conduction font partie des urgences de la sarcoïdose, avec les troubles du rythme ventriculaire."},{"t":"Les signes cliniques sont spécifiques : douleur angineuse typique à l'effort.","ok":false,"why":"Les signes sont non spécifiques : palpitations soutenues, malaises, syncope, signes d'insuffisance cardiaque."},{"t":"L'ECG n'est utile qu'en présence de symptômes cardiaques évocateurs.","ok":false,"why":"Il est indispensable dans toutes les formes, et à renouveler."}],"explanation":"L'atteinte cardiaque (BAV, bloc de branche droit, tachycardie ventriculaire, insuffisance cardiaque, mort subite) engage le pronostic vital : l'ECG est indispensable dans toute sarcoïdose.","src":"p. 238, 240, 242"},{"id":"p211-qcm-111","type":"QRM","rank":"B","objective":"p211-obj-05","tags":["clinique"],"difficulty":2,"stem":"À propos de l'atteinte oculaire de la sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"L'uvéite antérieure aiguë se manifeste par un œil rouge et/ou une baisse d'acuité visuelle.","ok":true,"why":"Le diagnostic repose sur l'examen à la lampe à fente."},{"t":"Le diagnostic d'uvéite antérieure repose sur l'examen à la lampe à fente.","ok":true,"why":"C'est l'examen de référence cité par le Collège."},{"t":"Une uvéite postérieure, parfois latente, justifie une consultation ophtalmologique.","ok":true,"why":"Risque pour la vue et association fréquente à une atteinte neurologique centrale : la consultation ophtalmologique est systématique."},{"t":"L'atteinte oculaire est toujours symptomatique, avec œil rouge et baisse d'acuité visuelle.","ok":false,"why":"Elle peut être totalement asymptomatique."},{"t":"Les formes chroniques sont bénignes et ne menacent pas l'acuité visuelle à long terme.","ok":false,"why":"Les formes chroniques peuvent menacer l'acuité visuelle (synéchies irido-cristalliniennes, cataracte, glaucome)."}],"explanation":"L'atteinte oculaire (15 à 30 % des patients) peut être asymptomatique et menacer la vision : l'examen ophtalmologique fait partie du bilan initial systématique.","src":"p. 238, 242"},{"id":"p211-qcm-112","type":"QRM","rank":"B","objective":"p211-obj-05","tags":["clinique"],"difficulty":2,"stem":"Quelles associations « syndrome – description » sont exactes ?","options":[{"t":"Syndrome de Heerfordt – uvéo-parotidite fébrile, paralysie faciale, méningite aseptique","ok":true,"why":"Uvéo-parotidite bilatérale fébrile, paralysie faciale (ou autre nerf crânien) et méningite lymphocytaire aseptique."},{"t":"Syndrome de Mikulicz – hypertrophie des glandes lacrymales et salivaires","ok":true,"why":"Description du syndrome de Mikulicz."},{"t":"Lupus pernio – plaque violacée infiltrée du nez et des joues","ok":true,"why":"Elle prend un aspect en aile de papillon et s'observe surtout dans les formes chroniques."},{"t":"Syndrome de Löfgren – érythème noueux et adénopathies hilaires et médiastinales bilatérales","ok":true,"why":"Des arthrites des chevilles peuvent remplacer l'érythème noueux."},{"t":"Syndrome de Heerfordt – érythème noueux et adénopathies hilaires et médiastinales bilatérales","ok":false,"why":"C'est le syndrome de Löfgren ; le Heerfordt associe uvéo-parotidite, paralysie faciale et méningite lymphocytaire."}],"explanation":"Löfgren (érythème noueux + adénopathies bilatérales), Heerfordt (uvéo-parotidite fébrile + paralysie faciale + méningite lymphocytaire), Mikulicz (hypertrophie des glandes lacrymales et salivaires) et lupus pernio (nez, joues) sont des tableaux à connaître.","src":"p. 239-240"},{"id":"p211-qcm-113","type":"QRM","rank":"B","objective":"p211-obj-10","tags":["imagerie"],"difficulty":2,"stem":"À propos du scanner thoracique haute résolution dans la sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"Il ne change pas les stades, qui restent définis sur la radiographie standard.","ok":true,"why":"La classification en stades reste radiographique."},{"t":"Il devient indispensable si la présentation est non typique ou en cas de complication.","ok":true,"why":"Par exemple une fibrose, une hypertension pulmonaire, un aspergillome ou une néoplasie."},{"t":"Il est indispensable dans tous les cas, y compris pour un stade I typique.","ok":false,"why":"Il n'est pas indispensable en cas de stade I typique."},{"t":"Il est moins sensible que la radiographie standard pour détecter les anomalies.","ok":false,"why":"Il est plus sensible que le cliché standard."},{"t":"Il ne permet pas de distinguer lésions inflammatoires réversibles et lésions fibreuses irréversibles.","ok":false,"why":"Il aide à distinguer des lésions inflammatoires actives, réversibles, et des lésions fibreuses irréversibles."}],"explanation":"Le scanner est plus sensible que la radiographie, aide à distinguer lésions actives et fibreuses, mais ne modifie pas les stades ; il n'est pas indispensable au stade I typique.","src":"p. 235"},{"id":"p211-qcm-114","type":"QRM","rank":"B","objective":"p211-obj-10","tags":["imagerie"],"difficulty":2,"stem":"Quels aspects scanographiques sont caractéristiques de l'atteinte parenchymateuse de la sarcoïdose ?","options":[{"t":"Des micronodules confluents de distribution lymphatique.","ok":true,"why":"Micronodules bilatéraux, le long des axes péribroncho-vasculaires épaissis et des zones sous-pleurales."},{"t":"Un aspect « perlé » des scissures.","ok":true,"why":"Il traduit les micronodules disposés le long des scissures."},{"t":"Des micronodules de distribution non lymphatique.","ok":false,"why":"Cette distribution est atypique et doit faire rechercher un diagnostic différentiel."},{"t":"Une prédominance dans la moitié inférieure des poumons, aux bases.","ok":false,"why":"Les micronodules prédominent dans la moitié supérieure des poumons."},{"t":"Un rayon de miel sous-pleural à prédominance basale.","ok":false,"why":"Quand une fibrose existe, elle prédomine dans les parties supérieures et postérieures, avec un rayon de miel apical et postérieur."}],"explanation":"Les micronodules lymphatiques de la moitié supérieure, avec aspect perlé des scissures, sont caractéristiques ; le scanner détecte aussi plus précocement la fibrose débutante et l'aspergillome.","src":"p. 235-236, 244"},{"id":"p211-qcm-115","type":"QRM","rank":"B","objective":"p211-obj-11","tags":["diagnostic"],"difficulty":2,"stem":"À propos de la stratégie de prélèvement pour obtenir la preuve histologique d'une sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"On privilégie d'abord les sites d'accès aisé (peau, ganglion périphérique, glandes salivaires).","ok":true,"why":"Les sites sont hiérarchisés selon leur caractère invasif, leur rentabilité et les organes atteints."},{"t":"Sans lésion superficielle, on envisage des biopsies bronchiques étagées.","ok":true,"why":"Les biopsies bronchiques étagées proximales ont un bon rendement diagnostique."},{"t":"La biopsie pulmonaire chirurgicale est le premier geste à proposer pour obtenir des granulomes.","ok":false,"why":"Elle est exceptionnellement nécessaire pour le diagnostic."},{"t":"La médiastinoscopie reste la technique de référence actuelle pour toutes les adénopathies médiastinales.","ok":false,"why":"Elle est très rarement réalisée, supplantée par la ponction à l'aiguille guidée par écho-endoscopie bronchique."},{"t":"Les biopsies transbronchiques sont moins sensibles que les biopsies bronchiques.","ok":false,"why":"Elles sont plus sensibles mais exposent à un risque faible d'hémorragie ou de pneumothorax."}],"explanation":"On prélève d'abord les sites faciles, puis les biopsies bronchiques ; en cas de négativité, biopsies transbronchiques, ponction ganglionnaire écho-guidée, glandes salivaires accessoires, biopsie hépatique, TEP orientée ou médiastinoscopie.","src":"p. 237, 243"},{"id":"p211-qcm-116","type":"QRM","rank":"B","objective":"p211-obj-11","tags":["biologie","diagnostic"],"difficulty":2,"stem":"À propos de l'endoscopie bronchique dans la sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"Son intérêt est essentiellement diagnostique, mais elle n'est pas systématique.","ok":true,"why":"Elle est inutile si le diagnostic a pu être obtenu par un prélèvement d'un site plus facilement accessible."},{"t":"Le LBA montre typiquement une alvéolite lymphocytaire modérée à lymphocytes T CD4+.","ok":true,"why":"L'alvéolite est de 20 à 50 %."},{"t":"Un rapport CD4/CD8 augmenté évoque la sarcoïdose mais ne suffit pas à l'affirmer.","ok":true,"why":"Il est inconstant."},{"t":"Les biopsies bronchiques étagées ont une sensibilité d'environ 90 % pour les granulomes.","ok":false,"why":"La sensibilité est de 50 à 60 % pour la détection des granulomes."},{"t":"Un rapport CD4/CD8 supérieur à 3,5 permet à lui seul d'affirmer le diagnostic de sarcoïdose.","ok":false,"why":"Ce rapport est en faveur de la sarcoïdose, mais il est inconstant et ne permet pas de conclure à lui seul."}],"explanation":"L'endoscopie bronchique permet des biopsies étagées (sensibilité 50 à 60 %) et un LBA d'orientation (alvéolite lymphocytaire CD4+, CD4/CD8 augmenté), sans valeur de certitude pour le LBA.","src":"p. 236-237"},{"id":"p211-qcm-117","type":"QRM","rank":"B","objective":"p211-obj-12","tags":["paraclinique"],"difficulty":2,"stem":"À propos des EFR au cours de la sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"La spirométrie est normale ou peu altérée au stade I.","ok":true,"why":"Elle l'est aussi dans les atteintes parenchymateuses minimes ; les EFR doivent néanmoins être systématiques."},{"t":"Syndrome restrictif ou mixte, plus rarement obstructif isolé.","ok":true,"why":"C'est le profil ventilatoire habituel."},{"t":"La DLCO diminue précocement.","ok":true,"why":"Elle reflète l'atteinte de la diffusion alvéolo-capillaire."},{"t":"Les gaz du sang sont longtemps normaux au repos.","ok":true,"why":"Le test de marche de 6 minutes peut montrer une désaturation à l'effort."},{"t":"Le test de marche de 6 minutes ne permet pas de détecter une désaturation à l'effort.","ok":false,"why":"Il objective une marche raccourcie et une désaturation à l'effort, qui peuvent refléter une insuffisance respiratoire ou une hypertension pulmonaire."}],"explanation":"Les EFR sont systématiques : spirométrie normale ou peu altérée au stade I, syndrome restrictif ou mixte, baisse précoce de la DLCO, gaz du sang normaux au repos et test de marche de 6 minutes pour la désaturation d'effort.","src":"p. 236"},{"id":"p211-qcm-118","type":"QRM","rank":"B","objective":"p211-obj-14","tags":["suivi"],"difficulty":2,"stem":"À propos de l'évolution et du suivi de la sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"Près de la moitié des patients ont une résolution spontanée dans les 2 ans.","ok":true,"why":"Après 5 ans d'évolution, une rémission est très peu probable."},{"t":"Les formes chroniques correspondent à une évolution d'au moins 3 à 5 ans.","ok":true,"why":"Les formes aiguës évoluent depuis moins de 2 ans."},{"t":"Les patients sont revus tous les 3 à 6 mois jusqu'à la guérison.","ok":true,"why":"Avec radiographie de thorax, EFR, ECA, biologie et ECG."},{"t":"Les rechutes surviennent surtout plus de 3 ans après l'arrêt de tout traitement.","ok":false,"why":"Elles surviennent le plus souvent dans les 2 à 6 mois après l'arrêt du traitement et sont exceptionnelles après 3 ans."},{"t":"La guérison est définie par 6 mois de rémission hors traitement.","ok":false,"why":"La guérison est une rémission stable hors traitement pendant 3 ans."}],"explanation":"La sarcoïdose est aiguë (moins de 2 ans) ou chronique (3 à 5 ans et plus) ; suivi tous les 3 à 6 mois, rechutes dans les 2 à 6 mois suivant l'arrêt du traitement, guérison après 3 ans de rémission stable hors traitement.","src":"p. 244"},{"id":"p211-qcm-119","type":"QRM","rank":"B","objective":"p211-obj-14","tags":["complications","suivi"],"difficulty":2,"stem":"À propos du pronostic de la sarcoïdose, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La fibrose pulmonaire est le principal risque évolutif pulmonaire.","ok":true,"why":"Elle peut entraîner une insuffisance respiratoire chronique, une hypertension pulmonaire et une infection aspergillaire chronique."},{"t":"L'atteinte cardiaque est la première cause de mortalité de la sarcoïdose en Occident.","ok":false,"why":"L'atteinte cardiaque est la deuxième cause ; la fibrose pulmonaire est la principale cause de mortalité en Occident."},{"t":"Le pronostic est défavorable chez la majorité des patients, avec séquelles fréquentes.","ok":false,"why":"Il est favorable dans 80 % des cas, avec ou sans traitement."},{"t":"Plus de 20 % des patients décèdent de leur sarcoïdose.","ok":false,"why":"1 à 5 % des patients décèdent de leur sarcoïdose ; 10 à 20 % gardent des séquelles."},{"t":"Une rémission reste fréquente après 5 ans d'évolution.","ok":false,"why":"Après 5 ans d'évolution, une rémission est très peu probable."}],"explanation":"Le pronostic est favorable dans 80 % des cas ; 10 à 20 % des patients gardent des séquelles et 1 à 5 % décèdent, surtout de fibrose pulmonaire.","src":"p. 244-245"},{"id":"p211-qcm-120","type":"QRM","rank":"B","objective":"p211-obj-13","tags":["épidémiologie"],"difficulty":1,"stem":"À propos de l'épidémiologie de la sarcoïdose, quelles propositions sont exactes ?","options":[{"t":"La prévalence varie selon l'ethnie, l'âge, le sexe et la zone géographique.","ok":true,"why":"L'affection est ubiquitaire dans le monde."},{"t":"Elle est plus fréquente et plus sévère chez les Afro-Américains et Caribéens.","ok":true,"why":"Elle y est trois fois plus fréquente."},{"t":"Elle débute dans deux tiers des cas entre 25 et 45 ans.","ok":true,"why":"Elle débute rarement avant 15 ans et après 75 ans."},{"t":"Elle touche nettement plus les hommes que les femmes, avec un sexe ratio F/M inférieur à 1.","ok":false,"why":"Il existe une discrète prépondérance féminine (sexe ratio F/M entre 1 et 1,5)."},{"t":"Les formes familiales représentent plus de la moitié des cas de sarcoïdose.","ok":false,"why":"Les formes familiales représentent moins de 10 % des cas."}],"explanation":"La sarcoïdose touche surtout l'adulte de 25 à 45 ans, avec une discrète prédominance féminine, et sa prévalence varie fortement selon l'ethnie (30 pour 100 000 en France).","src":"p. 232"},{"id":"p211-qru-101","type":"QRU","rank":"A","objective":"p211-obj-04","tags":["définition","clinique"],"difficulty":1,"stem":"Parmi les propositions suivantes, laquelle correspond au syndrome de Löfgren ?","options":[{"t":"Érythème noueux et adénopathies hilaires et médiastinales bilatérales","ok":true,"why":"C'est la définition du syndrome de Löfgren, forme aiguë de sarcoïdose souvent fébrile."},{"t":"Uvéo-parotidite bilatérale fébrile, paralysie faciale et méningite lymphocytaire","ok":false,"why":"C'est le syndrome de Heerfordt."},{"t":"Hypertrophie des glandes lacrymales et salivaires","ok":false,"why":"C'est le syndrome de Mikulicz."},{"t":"Plaque violacée infiltrée du nez et des joues avec atteinte ORL","ok":false,"why":"C'est le lupus pernio, qui doit faire rechercher une atteinte ORL."},{"t":"Hypercalcémie et trouble de conduction cardiaque","ok":false,"why":"Ce sont les deux situations d'urgence de la sarcoïdose."}],"explanation":"Le syndrome de Löfgren associe érythème noueux (ou arthrites des chevilles) et adénopathies hilaires et médiastinales bilatérales ; son évolution est spontanément favorable dans plus de 90 % des cas.","src":"p. 231, 239-240"},{"id":"p211-qru-102","type":"QRU","rank":"A","objective":"p211-obj-01","tags":["clinique","pièges"],"difficulty":2,"stem":"À propos de l'érythème noueux de la sarcoïdose, quelle proposition est exacte ?","options":[{"t":"La biopsie cutanée est inutile car la lésion est aspécifique.","ok":true,"why":"La biopsie ne montre pas de granulome."},{"t":"La biopsie montre des granulomes sans nécrose caséeuse, qui confirment la sarcoïdose.","ok":false,"why":"L'érythème noueux est une lésion aspécifique, sans granulome."},{"t":"Il prédomine sur le nez et les joues.","ok":false,"why":"Il prédomine sur les faces d'extension des membres, notamment les jambes ; le nez et les joues sont le siège du lupus pernio."},{"t":"Il siège surtout sur les faces de flexion des membres.","ok":false,"why":"Il prédomine sur les faces d'extension."},{"t":"C'est une lésion cutanée spécifique de la sarcoïdose.","ok":false,"why":"C'est une lésion aspécifique, même si la sarcoïdose en est la cause la plus fréquente en France."}],"explanation":"L'érythème noueux, dermo-hypodermite inflammatoire aiguë des faces d'extension des membres, est aspécifique : on ne le biopsie pas. Associé à des adénopathies hilaires et médiastinales bilatérales, il définit le syndrome de Löfgren.","trap":"Un érythème noueux ne montre pas de granulome : inutile de le biopsier.","src":"p. 239"},{"id":"p211-qru-103","type":"QRU","rank":"A","objective":"p211-obj-03","tags":["diagnostic"],"difficulty":1,"stem":"Quel élément est le plus souvent nécessaire pour affirmer le diagnostic de sarcoïdose ?","options":[{"t":"Des granulomes typiques sans nécrose caséeuse à l'histologie","ok":true,"why":"C'est le plus souvent nécessaire, sauf pour certains tableaux quasi pathognomoniques."},{"t":"Une ECA sérique élevée, corrélée à l'activité de la maladie","ok":false,"why":"Elle est peu sensible (environ 60 %) et non spécifique."},{"t":"Un rapport CD4/CD8 supérieur à 3,5 dans le liquide de lavage broncho-alvéolaire","ok":false,"why":"Il oriente vers la sarcoïdose, mais il est inconstant et ne permet pas d'affirmer le diagnostic à lui seul."},{"t":"Un test tuberculinique négatif (anergie tuberculinique)","ok":false,"why":"Il oriente (environ 80 % des cas) mais n'est pas spécifique."},{"t":"Une hypercalciurie, retrouvée de façon fréquente","ok":false,"why":"Elle est fréquente mais non spécifique : aucun examen biologique n'est spécifique."}],"explanation":"Le diagnostic repose sur un tableau compatible, des granulomes typiques et l'élimination des autres granulomatoses ; aucun examen biologique n'est spécifique.","src":"p. 237, 241-242"},{"id":"p211-qru-104","type":"QRU","rank":"B","objective":"p211-obj-09","tags":["biologie"],"difficulty":2,"stem":"Quelle proposition est exacte à propos de l'enzyme de conversion de l'angiotensine (ECA) sérique dans la sarcoïdose ?","options":[{"t":"Elle est peu sensible (≈ 60 % des cas) et non spécifique.","ok":true,"why":"Elle est élevée dans environ 60 % des cas et peut s'élever dans d'autres affections."},{"t":"Elle est élevée dans plus de 90 % des cas et spécifique de la maladie.","ok":false,"why":"Elle est élevée dans environ 60 % des cas et non spécifique."},{"t":"Elle reste interprétable chez les patients qui prennent un IEC.","ok":false,"why":"Elle est ininterprétable chez les patients sous inhibiteurs de l'enzyme de conversion."},{"t":"Elle est produite par les lymphocytes T CD4+ du granulome.","ok":false,"why":"Elle est produite par les macrophages activés des granulomes."},{"t":"Elle reflète le niveau de la calcémie.","ok":false,"why":"Elle traduit l'étendue de la masse granulomateuse et est corrélée à l'activité de la maladie."}],"explanation":"L'ECA, produite par les macrophages activés des granulomes, traduit l'étendue de la masse granulomateuse mais reste peu sensible, non spécifique et ininterprétable sous IEC.","src":"p. 241"},{"id":"p211-qru-105","type":"QRU","rank":"B","objective":"p211-obj-05","tags":["clinique"],"difficulty":2,"stem":"Quelle manifestation cutanée de la sarcoïdose doit faire rechercher une atteinte ORL ?","options":[{"t":"Le lupus pernio","ok":true,"why":"Plaque violacée infiltrée du nez et des joues, surtout dans les formes chroniques : elle impose de rechercher une atteinte ORL."},{"t":"L'érythème noueux","ok":false,"why":"Il est aspécifique et fait partie du syndrome de Löfgren."},{"t":"Les sarcoïdes en plaques","ok":false,"why":"Le Collège ne les associe pas à la recherche d'une atteinte ORL."},{"t":"Les nodules sur cicatrice","ok":false,"why":"Le Collège ne les associe pas à la recherche d'une atteinte ORL."},{"t":"Les nodules sous-cutanés","ok":false,"why":"Le Collège ne les associe pas à la recherche d'une atteinte ORL."}],"explanation":"Le lupus pernio, observé surtout dans les formes chroniques, doit faire rechercher une atteinte ORL.","src":"p. 238-239"},{"id":"p211-qru-106","type":"QRU","rank":"B","objective":"p211-obj-14","tags":["complications"],"difficulty":2,"stem":"Quelle est la principale cause de mortalité par sarcoïdose en Occident ?","options":[{"t":"La fibrose pulmonaire","ok":true,"why":"C'est la principale cause de mortalité par sarcoïdose en Occident."},{"t":"L'atteinte cardiaque","ok":false,"why":"C'est la deuxième cause de mortalité (insuffisance cardiaque, mort subite)."},{"t":"L'atteinte du système nerveux central","ok":false,"why":"Elle peut engager le pronostic vital, mais n'est pas la principale cause de mortalité."},{"t":"L'atteinte hépatique","ok":false,"why":"Elle est source de morbidité importante, mais pas de la principale mortalité."},{"t":"L'atteinte oculaire","ok":false,"why":"Elle menace le pronostic visuel (cécité), pas la vie."}],"explanation":"La fibrose pulmonaire est le principal risque évolutif et la principale cause de mortalité par sarcoïdose en Occident ; l'atteinte cardiaque est la deuxième.","src":"p. 240, 245"},{"id":"p211-qru-107","type":"QRU","rank":"B","objective":"p211-obj-10","tags":["imagerie"],"difficulty":2,"stem":"Chez un patient asymptomatique, la radiographie de thorax montre des adénopathies hilaires bilatérales symétriques sans atteinte parenchymateuse. Que dire du scanner thoracique ?","options":[{"t":"Il n'est pas indispensable si ce stade I est typique.","ok":true,"why":"Le scanner n'est pas indispensable en cas de stade I typique."},{"t":"Il est indispensable avant toute surveillance.","ok":false,"why":"Il n'est indispensable qu'en cas de présentation non typique ou de complication suspectée."},{"t":"Il est contre-indiqué.","ok":false,"why":"Il est simplement non indispensable dans ce cas ; il est utile dans les autres."},{"t":"Il est indispensable pour classer le stade.","ok":false,"why":"La classification en stades repose sur la radiographie standard."},{"t":"Il doit être remplacé par un TEP-scanner systématique.","ok":false,"why":"La TEP-FDG n'a pas de place en routine (coût, irradiation)."}],"explanation":"Au stade I typique, le scanner n'est pas indispensable ; il devient indispensable devant une présentation non typique ou une complication suspectée.","src":"p. 235, 237"},{"id":"p211-qru-108","type":"QRU","rank":"B","objective":"p211-obj-11","tags":["diagnostic"],"difficulty":1,"stem":"Chez un patient suspect de sarcoïdose qui présente une lésion cutanée accessible, quel est le site de biopsie à privilégier ?","options":[{"t":"La lésion cutanée","ok":true,"why":"On privilégie les sites d'accès aisé."},{"t":"Le parenchyme pulmonaire par biopsie chirurgicale","ok":false,"why":"La biopsie pulmonaire est exceptionnellement nécessaire pour le diagnostic."},{"t":"Les ganglions médiastinaux par médiastinoscopie","ok":false,"why":"La médiastinoscopie est très rarement réalisée, car supplantée par la ponction écho-guidée."},{"t":"Le foie par biopsie hépatique","ok":false,"why":"Elle n'est discutée qu'en cas d'anomalie biologique hépatique, après les sites faciles."},{"t":"Le poumon par biopsie transbronchique","ok":false,"why":"Elle se discute si les premiers prélèvements sont négatifs, en cas d'atteinte parenchymateuse."}],"explanation":"Les sites de prélèvement sont hiérarchisés : d'abord les sites d'accès aisé (lésion cutanée, adénopathie périphérique, glandes salivaires accessoires, nodule conjonctival), puis l'endoscopie bronchique.","src":"p. 243"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p211-pareto","points":[{"id":"p211-par-01","rank":"A","cat":"définition","text":"Sarcoïdose = maladie **systémique** de cause **inconnue**, à **granulomes épithélioïdes et giganto-cellulaires sans nécrose caséeuse** ; diagnostic d'élimination des autres granulomatoses","src":"p. 231-232"},{"id":"p211-par-02","rank":"A","cat":"définition","text":"Diagnostic = tableau **clinico-radiologique compatible** + **granulomes typiques** + **élimination des autres granulomatoses** ; aucun examen biologique n'est spécifique","src":"p. 242"},{"id":"p211-par-03","rank":"A","cat":"clinique","text":"**Löfgren** = **érythème noueux** (ou arthrites des chevilles) + **ADP hilaires et médiastinales bilatérales** ; souvent fébrile, femme d'Europe du Nord ; guérison spontanée > 90 % en 12-24 mois","src":"p. 239-240"},{"id":"p211-par-04","rank":"A","cat":"piège","text":"Érythème noueux = lésion aspécifique, **biopsie inutile** ; Löfgren, **Heerfordt**, **lupus pernio** + ADP médiastino-hilaires bilatérales = diagnostic sans biopsie","src":"p. 239, 242"},{"id":"p211-par-05","rank":"A","cat":"clinique","text":"Atteinte médiastino-pulmonaire ~**90 %** : toux sèche, dyspnée rare au début, **auscultation normale** ; radiographie très atteinte mais **clinique discrète** = en faveur du diagnostic","src":"p. 232-234"},{"id":"p211-par-06","rank":"A","cat":"examen","text":"Stades radiographiques : 0 normale ; **I** ADP hilaires bilatérales seules ; II ADP + atteinte parenchymateuse ; **III** parenchyme isolé ; **IV** fibrose (apicale)","src":"p. 233"},{"id":"p211-par-07","rank":"B","cat":"examen","text":"ADP typiques : hilaires **bilatérales symétriques non compressives** (95 %) ; scanner : micronodules **lymphatiques** (scissures « perlées »), non indispensable si **stade I typique**","src":"p. 234-235"},{"id":"p211-par-08","rank":"B","cat":"gravité","text":"**2 urgences** : **hypercalcémie** (soleil, calcium, vitamine D) et **trouble de conduction** cardiaque ; ECG indispensable dans toute sarcoïdose, à renouveler","src":"p. 231, 240-241"},{"id":"p211-par-09","rank":"B","cat":"examen","text":"Biologie : **hypercalciurie**, lymphopénie CD4, hypergammaglobulinémie polyclonale, test tuberculinique négatif (80 %) ; **ECA** peu sensible (60 %), non spécifique, ininterprétable sous **IEC**","src":"p. 241"},{"id":"p211-par-10","rank":"B","cat":"clinique","text":"Extra-respiratoire fréquent : **peau, œil, ADP périphériques, foie** ; **lupus pernio** → rechercher une atteinte ORL ; Heerfordt = uvéo-parotidite fébrile + paralysie faciale + méningite","src":"p. 237-240"},{"id":"p211-par-11","rank":"B","cat":"examen","text":"Prélèvements : sites **d'accès aisé** d'abord, puis **biopsies bronchiques**, puis BTB / ponction écho-guidée ; LBA = alvéolite lymphocytaire, **CD4/CD8** augmenté (inconstant, non suffisant)","src":"p. 237, 243"},{"id":"p211-par-12","rank":"B","cat":"piège","text":"À éliminer : **tuberculose**, lymphome, médicaments (anti-TNF, interféron, check-point), VIH ; atypiques : fièvre, **râles crépitants**, hippocratisme, IDR positive, ADP unilatérales","src":"p. 241, 243-244"},{"id":"p211-par-13","rank":"B","cat":"examen","text":"EFR : spirométrie normale au stade I, syndrome **restrictif** ou mixte, baisse **précoce de la DLCO**, gaz du sang normaux au repos ; **TM6** pour la désaturation d'effort","src":"p. 236"},{"id":"p211-par-14","rank":"B","cat":"suivi","text":"~**1/2** de résolution spontanée en 2 ans ; aiguë < 2 ans, chronique ≥ 3-5 ans ; suivi **tous les 3-6 mois** ; guérison = **3 ans** de rémission hors traitement","src":"p. 244"},{"id":"p211-par-15","rank":"B","cat":"gravité","text":"**Fibrose** = principal risque évolutif (IRC, HTP, **aspergillose** avec hémoptysies) et 1re cause de mortalité ; atteinte cardiaque = 2e cause ; oculaire → cécité","src":"p. 240, 245"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
